c = collections.Counter(i['role'] for i in ITEMS)
n = len(ITEMS)
assert len({i['item'] for i in ITEMS}) == n and len({i['prompt'] for i in ITEMS}) == n
flash = sum(c[r] for r in ('executor', 'scribe', 'critic', 'sentinel', 'revenger', 'simplifier'))
attack = sum(c[r] for r in ('reviewer', 'critic', 'mutation-tester'))
assert 32 <= n <= 64 and flash * 2 >= n and attack * 4 >= n, (n, flash, attack)
spec = {'wave': 'souji-r32-a2w1', 'reportDir': '.ufo/waves/round-32/a2w1', 'maxLanes': 64, 'context': CONTEXT, 'items': ITEMS}
json.dump(spec, open(L + '/.ufo/waves/round-32/a2w1-spec.json', 'w'), ensure_ascii=False, indent=1)
print(n, dict(c), 'flash', flash, 'attack', attack)
